long longfactorial(int n) {
    // 1. 基线条件 (Base Case)
    if(n == 0) {
        return1;
    }
    // 2. 递归条件 (Recursive Case)
    returnn * factorial(n - 1);
}

int fibonacci(int n) {
// 基线条件判断
if(n == 0 )return0;
if(n == 1 )return1;
// 递推调用自身
return fibonacci(n-1) + fibonacci(n-2);
}

